export const DEMO_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"theme-color\" content=\"#111418\">\n<title>TetherDeck</title>\n<style>\n:root{\n  --bg:#111418; --bg2:#161b22; --bg3:#1e2530; --border:#2a313c;\n  --text:#e6e9ee; --dim:#9aa4b2; --dim2:#6b7686;\n  --accent:#3b82f6; --accent2:#2563eb; --user:#2563eb; --ok:#22c55e; --warn:#f59e0b; --err:#ef4444;\n}\n*{box-sizing:border-box; margin:0; padding:0; -webkit-tap-highlight-color:transparent;}\nhtml,body{height:100%;}\nbody{\n  background:var(--bg); color:var(--text);\n  font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n  font-size:15px; line-height:1.55; overflow:hidden;\n}\n.hidden{display:none !important;}\nbutton{font-family:inherit; cursor:pointer; border:none; background:var(--accent); color:#fff; border-radius:10px; padding:8px 14px; font-size:14px;}\nbutton:disabled{opacity:.45; cursor:default;}\nbutton.ghost{background:var(--bg3); color:var(--text); border:1px solid var(--border);}\nbutton.danger{background:#7f1d1d; color:#fecaca;}\ninput,textarea{font-family:inherit; font-size:15px; background:var(--bg2); color:var(--text); border:1px solid var(--border); border-radius:10px; padding:10px 12px; outline:none; width:100%;}\ninput:focus,textarea:focus{border-color:var(--accent);}\n\n/* ---------- login ---------- */\n#login{height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px; padding:24px;}\n#login .logo{font-size:44px;}\n#login h1{font-size:20px; font-weight:600;}\n#login p{color:var(--dim); font-size:13px; text-align:center;}\n#login .box{width:100%; max-width:320px; display:flex; flex-direction:column; gap:12px;}\n\n/* ---------- main UI ---------- */\n#app{height:100%; display:flex; flex-direction:column;}\nheader{\n  flex:0 0 auto; display:flex; align-items:center; gap:8px; padding:calc(10px + env(safe-area-inset-top)) 12px 10px;\n  background:var(--bg2); border-bottom:1px solid var(--border); flex-wrap:wrap;\n}\nheader select{\n  flex:1 1 auto; min-width:0; background:var(--bg3); color:var(--text); border:1px solid var(--border);\n  border-radius:8px; padding:7px 8px; font-size:13px; max-width:100%;\n}\nheader select#modelSel{flex:0 0 auto; max-width:34%;}\n.status{display:flex; align-items:center; gap:5px; font-size:12px; color:var(--dim); white-space:nowrap;}\n.dot{width:8px; height:8px; border-radius:50%; background:var(--dim2); flex:0 0 auto;}\n.dot.idle{background:var(--ok);} .dot.running{background:var(--warn); animation:pulse 1.2s infinite;}\n.dot.permission{background:var(--accent);} .dot.error,.dot.stopped{background:var(--err);} .dot.starting{background:var(--warn);}\n@keyframes pulse{50%{opacity:.4;}}\nheader button{padding:6px 10px; font-size:12px; border-radius:8px;}\n\n/* ---------- message area ---------- */\n#chat{flex:1 1 auto; overflow-y:auto; padding:14px 12px calc(12px + env(safe-area-inset-bottom)); display:flex; flex-direction:column; gap:10px;}\n.empty{color:var(--dim2); text-align:center; margin-top:30vh; font-size:14px;}\n.msg{max-width:86%; padding:9px 12px; border-radius:14px; font-size:14.5px; word-wrap:break-word; overflow-wrap:break-word; position:relative;}\n.msg.user{align-self:flex-end; background:var(--user); color:#fff; border-bottom-right-radius:4px; white-space:pre-wrap;}\n.msg.assistant{align-self:flex-start; background:var(--bg3); border-bottom-left-radius:4px;}\n.msg.tool{align-self:flex-start; width:100%; max-width:100%;}\n.msg.approval{align-self:center; width:100%; max-width:100%; background:var(--bg2); border:1px solid var(--accent); border-radius:14px; padding:12px;}\n.msg.error{align-self:center; width:100%; background:#2a1215; border:1px solid var(--err); color:#fca5a5; border-radius:12px; font-size:13px;}\n.msg.wide{max-width:100%;}\n\n/* Claude 回复原来用 textContent 直塞，换行和等宽对齐全丢。这里按代码块/表格/标题\n   轻量解析：正文保留 pre-wrap，代码和表格横向滚动，手机端也能看清对齐的列。 */\n.msg.assistant .mtext{white-space:pre-wrap; overflow-wrap:break-word; word-break:break-word;}\n.msg.assistant .mhead{font-weight:600; margin:8px 0 3px; color:var(--text);}\n.msg.assistant .mhead.h1{font-size:16.5px;} .msg.assistant .mhead.h2{font-size:15.5px;}\n.msg.assistant .mhead.h3,.msg.assistant .mhead.h4,.msg.assistant .mhead.h5,.msg.assistant .mhead.h6{font-size:14.5px;}\n.msg.assistant pre.code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace; font-size:12.5px; line-height:1.5; background:var(--bg2); border:1px solid var(--border); border-radius:8px; padding:8px 10px; margin:6px 0; overflow-x:auto; white-space:pre; -webkit-overflow-scrolling:touch;}\n.msg.assistant .mtable-wrap{overflow-x:auto; margin:6px 0; -webkit-overflow-scrolling:touch;}\n.msg.assistant .mtable{border-collapse:collapse; font-size:12.5px; white-space:nowrap;}\n.msg.assistant .mtable th,.msg.assistant .mtable td{border:1px solid var(--border); padding:4px 8px; text-align:left;}\n.msg.assistant .mtable th{background:var(--bg2); color:var(--text); font-weight:600;}\n.msg.assistant .mtable td{color:var(--dim);}\n.msg.assistant code.ic{font-family:ui-monospace,Consolas,monospace; font-size:12.5px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; padding:0 4px;}\n\n.thinking{color:var(--dim2); font-size:12.5px; border-left:2px solid var(--border); padding:2px 0 2px 8px; margin-bottom:6px;}\ndetails.thinking summary{cursor:pointer; color:var(--dim); font-size:12px; user-select:none;}\ndetails.thinking .body{margin-top:4px; white-space:pre-wrap;}\n\n.toolcard{border:1px solid var(--border); border-radius:8px; padding:6px 8px; margin:4px 0; background:var(--bg2);}\n.toolcard .tname{font-size:12px; color:var(--accent); font-weight:600; margin-bottom:3px;}\n.toolcard .tinput{font-size:11px; color:var(--dim); font-family:ui-monospace,Consolas,monospace; white-space:pre-wrap; max-height:120px; overflow:auto;}\n\n.msg.tool .tresult{font-size:12px; color:var(--dim); font-family:ui-monospace,Consolas,monospace; white-space:pre-wrap; background:var(--bg2); border:1px solid var(--border); border-radius:8px; padding:7px 9px;}\n.tresult.err{border-color:var(--err); color:#fca5a5;}\n\n.approval .ac-title{font-size:14px; font-weight:600; margin-bottom:6px;}\n.approval .ac-detail{font-size:12px; color:var(--dim); white-space:pre-wrap; background:var(--bg3); border-radius:6px; padding:6px 8px; margin-bottom:10px; font-family:ui-monospace,Consolas,monospace; max-height:140px; overflow:auto;}\n.approval .ac-actions{display:flex; gap:8px;}\n.approval .ac-actions button{flex:1; padding:9px; font-size:14px;}\n.approval .q-row{margin-bottom:10px;}\n.approval .q-text{font-size:13.5px; font-weight:500; margin-bottom:6px;}\n.approval .q-opts{display:flex; flex-wrap:wrap; gap:6px;}\n.approval .q-opt{background:var(--bg3); border:1px solid var(--border); color:var(--text); padding:7px 12px; border-radius:8px; font-size:13px;}\n.approval .q-opt.sel{border-color:var(--accent); background:var(--accent); color:#fff;}\n.approval .q-done{color:var(--ok); font-size:13px;}\n\n.typing{color:var(--dim2); font-size:13px; padding:4px 2px;}\n\n/* ---------- input bar ---------- */\n#inputbar{flex:0 0 auto; display:flex; align-items:flex-end; gap:8px; padding:10px 12px calc(10px + env(safe-area-inset-bottom)); background:var(--bg2); border-top:1px solid var(--border);}\n#inputbar textarea{flex:1; resize:none; max-height:120px; min-height:42px; line-height:1.4;}\n#inputbar button{padding:10px 16px; font-size:15px;}\n\n.toast{position:fixed; top:calc(14px + env(safe-area-inset-top)); left:50%; transform:translateX(-50%); background:#333a45; color:#fff; padding:8px 16px; border-radius:8px; font-size:13px; z-index:99; box-shadow:0 4px 12px rgba(0,0,0,.4); opacity:0; transition:opacity .2s;}\n.toast.show{opacity:1;}\n\n/* ---------- session history ---------- */\n#histOverlay{position:fixed; inset:0; background:var(--bg); z-index:50; display:flex; flex-direction:column;}\n.hist-head{flex:0 0 auto; display:flex; align-items:center; justify-content:space-between; padding:calc(12px + env(safe-area-inset-top)) 12px 10px; background:var(--bg2); border-bottom:1px solid var(--border); font-size:16px; font-weight:600;}\n.hist-head button{padding:6px 12px; font-size:13px;}\n#histList{flex:1 1 auto; overflow-y:auto; padding:10px 12px calc(12px + env(safe-area-inset-bottom)); display:flex; flex-direction:column; gap:8px;}\n.hist-item{background:var(--bg3); border:1px solid var(--border); border-radius:12px; padding:10px 12px; cursor:pointer;}\n.hist-item:active{background:var(--bg2);}\n.hist-title{font-size:14px; font-weight:600; color:var(--text); overflow:hidden; text-overflow:ellipsis; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; word-break:break-word;}\n.hist-meta{font-size:12px; color:var(--dim); margin-top:5px; display:flex; gap:8px; flex-wrap:wrap; align-items:center;}\n.hist-meta .proj{color:var(--accent);}\n.hist-empty{color:var(--dim2); text-align:center; margin-top:24vh; font-size:14px;}\n.msg.note{align-self:center; background:var(--bg2); border:1px dashed var(--border); color:var(--dim); font-size:12px; padding:6px 12px; border-radius:10px; max-width:95%; text-align:center;}\n#resumeTag{font-size:11px; color:var(--warn); background:#3b2f10; border:1px solid #6b5200; border-radius:6px; padding:2px 7px; white-space:nowrap;}\n\n/* iPhone Duo, unfolded: the status bar moves to the RIGHT edge and turns\n   vertical. Every rule above only consumes safe-area-inset-top/-bottom, which\n   were the only non-zero insets on a folded phone. Unfolded, left/right are\n   non-zero too, and without them the right edge of each screen sits under that\n   vertical status bar. These two rules add horizontal insets only, keeping the\n   original 24px/12px base padding and the full-bleed backgrounds of the header\n   and input bar. Folded, both insets are 0 — pixel-identical to before. */\n#login{\n  padding-left:calc(24px + env(safe-area-inset-left));\n  padding-right:calc(24px + env(safe-area-inset-right));\n}\nheader, #chat, #inputbar, .hist-head, #histList{\n  padding-left:calc(12px + env(safe-area-inset-left));\n  padding-right:calc(12px + env(safe-area-inset-right));\n}\n</style>\n</head>\n<body>\n\n<div id=\"login\">\n  <div class=\"logo\">🤖</div>\n  <h1>TetherDeck</h1>\n  <p>Connect to Claude Code running on your computer</p>\n  <div class=\"box\">\n    <input id=\"tokenInput\" type=\"password\" placeholder=\"Connection token\" autocomplete=\"off\" autofocus>\n    <button id=\"btnLogin\">Connect</button>\n  </div>\n</div>\n\n<div id=\"app\" class=\"hidden\">\n  <header>\n    <select id=\"projectSel\"></select>\n    <select id=\"modelSel\" title=\"Model\"></select>\n    <span class=\"status\"><span id=\"dot\" class=\"dot\"></span><span id=\"stext\">Disconnected</span></span>\n    <span id=\"resumeTag\" class=\"hidden\"></span>\n    <button id=\"btnNew\" class=\"ghost\" title=\"New session\">New session</button>\n    <button id=\"btnHist\" class=\"ghost\" title=\"Session history\">📚 History</button>\n    <button id=\"btnStop\" class=\"ghost danger\" title=\"Stop current task\">Stop</button>\n  </header>\n  <main id=\"chat\"><div class=\"empty\">Connecting…</div></main>\n  <footer id=\"inputbar\">\n    <textarea id=\"msgInput\" rows=\"1\" placeholder=\"Message Claude…\"></textarea>\n    <button id=\"btnSend\">Send</button>\n  </footer>\n</div>\n\n<div id=\"histOverlay\" class=\"hidden\">\n  <div class=\"hist-head\">\n    <span>📚 History (tap to resume)</span>\n    <button id=\"histClose\" class=\"ghost\">Close</button>\n  </div>\n  <div id=\"histList\"></div>\n</div>\n\n<div id=\"toast\" class=\"toast\"></div>\n\n<script>window.__TETHERDECK_DEMO__ = true;</script>\n<script>\n'use strict';\nlet state = null, es = null;\nconst $ = (id) => document.getElementById(id);\nconst chat = $('chat');\n// 内置 Demo 模式：由手机壳 app 以本地 HTML 载入（无服务器、无网络请求），供 App Review 直接体验\nconst DEMO = !!window.__TETHERDECK_DEMO__;\nfunction lsGet(k){ try { return localStorage.getItem(k); } catch(e){ return null; } }\nconst savedToken = DEMO ? 'demo' : lsGet('ccb_token');\n\nfunction toast(msg, ms){ const t=$('toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove('show'), ms||2200); }\n\nasync function api(path, body){\n  if (DEMO) return demoApi(path, body);\n  const opt = { method: body ? 'POST':'GET', headers:{} };\n  if (body){ opt.headers['Content-Type']='application/json'; opt.body=JSON.stringify(body); }\n  const r = await fetch(path, opt);\n  if (r.status===401){ showLogin(); return null; }\n  try { return await r.json(); } catch { return {}; }\n}\n\n/* ---------- demo mode: bundled sample data, zero network ---------- */\nconst DEMO_PROJECTS = ['~/Projects/tetherdeck-demo', '~/Projects/api-server'];\nconst DEMO_SESSIONS = [\n  { id:'demo-s-1', title:'Add health-check endpoint', project:'~/Projects/tetherdeck-demo', model:'claude', size:48213, lastAt: Date.now()-1000*60*12, firstMsg:'Add a health-check endpoint to the API and show me the diff.' },\n  { id:'demo-s-2', title:'Fix flaky login test', project:'~/Projects/api-server', model:'claude', size:30177, lastAt: Date.now()-1000*60*60*5, firstMsg:'The login test fails one run in three. Find the cause.' },\n  { id:'demo-s-3', title:'Refactor config loader', project:'~/Projects/tetherdeck-demo', model:'claude', size:88904, lastAt: Date.now()-1000*60*60*27, firstMsg:'Split config loading into its own module.' }\n];\nlet demo = null;\n\nfunction demoSeed(project){\n  demo = {\n    project: project || DEMO_PROJECTS[0],\n    status: 'idle',\n    sessionId: 'demo-session-001',\n    resumeId: null,\n    messages: [\n      { role:'user', text:'Add a health-check endpoint to the API and show me the diff.' },\n      { role:'assistant', thinking:'The demo server uses Express. I will add GET /health and a matching test.', text:'I found the Express app. Adding a /health route plus a small test.',\n        tools:[{name:'Read', input:'src/server.js'}, {name:'Edit', input:'src/server.js  +  app.get(\\'/health\\', …)'}] },\n      { role:'tool', results:[{text:'Read 42 lines from src/server.js'}] },\n      { role:'user', text:'Also add a test and run the whole suite.' },\n      { role:'assistant', thinking:'A tiny supertest case covers the route without booting a port.', text:'Added test/health.test.js. The suite is green: 18 passed, 0 failed.',\n        tools:[{name:'Write', input:'test/health.test.js'}, {name:'Bash', input:'npm test'}] },\n      { role:'tool', results:[{text:'PASS test/health.test.js  (2 tests)'}, {text:'Tests: 18 passed, 0 failed'}] },\n      { role:'approval', card:{ toolName:'Edit', input:'src/server.js — add GET /health', requestId:'demo-perm-001' } }\n    ]\n  };\n}\nfunction demoSnapshot(){\n  if (!demo) demoSeed();\n  return {\n    project: demo.project,\n    projects: DEMO_PROJECTS,\n    status: demo.status,\n    sessionId: demo.sessionId,\n    resumeId: demo.resumeId,\n    model: 'claude',\n    modelPref: demo.modelPref || null,\n    modelOptions: [\n      { id:'', label:'Default', title:'Default · claude' },\n      { id:'opus', label:'Opus', title:'Opus · claude-opus' },\n      { id:'sonnet', label:'Sonnet', title:'Sonnet · claude-sonnet' },\n      { id:'haiku', label:'Haiku', title:'Haiku · claude-haiku' }\n    ],\n    messages: demo.messages\n  };\n}\nfunction demoApi(path, body){\n  if (!demo) demoSeed();\n  if (path === '/api/state') return Promise.resolve(demoSnapshot());\n  if (path === '/api/projects') return Promise.resolve({ projects: DEMO_PROJECTS });\n  if (path === '/api/sessions') return Promise.resolve({ sessions: DEMO_SESSIONS });\n  if (path === '/api/session'){\n    demoSeed((body && body.project) || demo.project);\n    if (body && body.resumeId){\n      const s = DEMO_SESSIONS.find(x => x.id === body.resumeId);\n      demo.resumeId = body.resumeId;\n      demo.project = (s && s.project) || demo.project;\n      demo.messages = [\n        { role:'note', text:'Resumed demo session — sample transcript.' },\n        { role:'user', text:(s && s.firstMsg) || 'Continue where we left off.' },\n        { role:'assistant', text:'Previous work restored. The last change was a /health route plus its test. Ready for the next step.' }\n      ];\n    }\n    render();\n    return Promise.resolve(demoSnapshot());\n  }\n  if (path === '/api/stop'){ demo.status='idle'; render(); return Promise.resolve(demoSnapshot()); }\n  if (path === '/api/runner/model'){ demo.modelPref = (body && body.model) || null; render(); return Promise.resolve(demoSnapshot()); }\n  if (path === '/api/message'){\n    const text = (body && body.text) || '';\n    demo.messages.push({ role:'user', text });\n    demo.status = 'running'; render();\n    setTimeout(() => {\n      if (!demo) return;\n      demo.messages.push({ role:'assistant', text:'This is demo mode. In the real app, Claude Code on your computer runs the task and streams the result here.' });\n      demo.status = 'idle'; render();\n    }, 1200);\n    return Promise.resolve(demoSnapshot());\n  }\n  if (path === '/api/approve'){\n    const id = body && body.requestId;\n    const allow = body && body.decision !== 'deny';\n    const i = demo.messages.findIndex(m => m.role === 'approval' && m.card && m.card.requestId === id);\n    if (i >= 0) demo.messages[i] = { role:'note', text: allow ? '✅ Allowed (demo)' : '❌ Denied (demo)' };\n    render();\n    setTimeout(() => {\n      if (!demo) return;\n      demo.messages.push({ role:'assistant', text: allow ? 'Done — GET /health returns 200 OK. I also added test/health.test.js.' : 'Understood — I will leave the file unchanged.' });\n      demo.status = 'idle'; render();\n    }, 900);\n    return Promise.resolve(demoSnapshot());\n  }\n  return Promise.resolve({});\n}\n\n/* ---------- native shell commands (iOS app injects these) ---------- */\nfunction postNative(obj){\n  try { if (window.ReactNativeWebView && window.ReactNativeWebView.postMessage) window.ReactNativeWebView.postMessage(JSON.stringify(obj)); } catch(e){}\n}\nwindow.__tdNative = async function(cmd, arg){\n  try {\n    if (cmd === 'sessions'){\n      const r = await api('/api/sessions');\n      postNative({ type:'td-sessions', sessions:(r && r.sessions) || [] });\n    } else if (cmd === 'resume'){\n      const s = await api('/api/session', { project: arg && arg.project, fresh:false, resumeId: arg && arg.resumeId });\n      if (s) { state = s; render(); }\n      // holders/released: 电脑端是否正开着这条会话 / 已让它让位\n      postNative({ type:'td-resumed', ok: !!s, holders:(s && s.holders) || [], released:(s && s.released) || [] });\n    } else if (cmd === 'approve'){\n      const r = await api('/api/approve', { requestId: arg && arg.requestId, decision: arg && arg.decision });\n      postNative({ type:'td-approved', ok: !!(r && (r.ok || r.sessionId || r.messages)) });\n    }\n  } catch(e){ postNative({ type:'td-error', cmd:cmd, message:String(e) }); }\n};\n\n// 回前台快速重连: 只重开 SSE, 不重载页面(原生壳在 2.5s 内没收到回执才整页 reload)\n// [2026-11-22] 回执必须等 SSE 真的 open 之后才发。原来这里 connect() 后立刻回执,\n// 原生壳的 2.5s 兜底 reload 每次都被提前解除; 链路已死时页面永远停在\n// \"Reconnecting…\", 既不 reload 也不报导航错误, 于是自动换地址永远不触发。\nwindow.__tdReconnect = function(){\n  try { if (es) es.close(); } catch(e){}\n  connect();\n  return true;\n};\n// connect() 的 onopen 里发回执, 见下方 connect 定义。\n\nfunction showLogin(){ $('app').classList.add('hidden'); $('login').classList.remove('hidden'); }\nasync function doLogin(){\n  const t = $('tokenInput').value.trim();\n  const r = await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:t})});\n  if (r.ok){ localStorage.setItem('ccb_token', t); start(); } else toast('Invalid token');\n}\n\nfunction connect(){\n  if (es) es.close();\n  es = new EventSource('/api/sse');\n  es.addEventListener('state', e => { try { state = JSON.parse(e.data); render(); } catch(err){} });\n  // 连接真正建立才算重连成功: 原生壳据此取消 2.5s 的整页 reload 兜底\n  es.onopen = () => { setStatus('Connected'); postNative({ type:'td-reconnected' }); };\n  es.onerror = () => setStatus('Reconnecting…');\n}\n\nfunction setStatus(t){\n  $('stext').textContent = t;\n  $('dot').className = 'dot ' + (state ? (state.status||'idle') : '');\n}\n\n/* ---------- rendering ---------- */\nfunction esc(s){ return String(s == null ? '' : s); }\nfunction fmtInput(input){\n  let s = input;\n  if (typeof s !== 'string') s = JSON.stringify(s, null, 1);\n  return s.length > 400 ? s.slice(0,400)+'…' : s;\n}\n\n/* 增量渲染:流式期间服务端每 ~120ms 推一包快照。原来每包都 chat.innerHTML=''\n   重建全部消息节点,长会话(几百条)会明显卡顿。这里按 id 前缀比对,只改动\n   真正变化的部分 —— 追加就 append,最后一条在增长就只重建那一条。 */\nlet renderedIds = [], nodeById = new Map(), sigById = new Map(), emptyEl = null, typingEl = null, lastProjKey = '', lastModelsKey = '', draftRestored = false;\n\nfunction msgSig(m){\n  return (m.role||'')+'|'+(m.text?String(m.text).length:0)+'|'+(m.thinking?String(m.thinking).length:0)\n    +'|'+((m.tools&&m.tools.length)||0)+'|'+((m.results&&m.results.length)||0)\n    +'|'+((m.card&&m.card.requestId)||'');\n}\nfunction clearChatNodes(){\n  chat.innerHTML = '';\n  renderedIds = []; nodeById = new Map(); sigById = new Map(); emptyEl = null; typingEl = null;\n}\n\nfunction renderHead(){\n  const sel = $('projectSel');\n  const prev = sel.value;\n  const projKey = (state.projects||[]).join('\\u0000') + '\\u0001' + (state.project||'');\n  if (projKey !== lastProjKey){\n    lastProjKey = projKey;\n    sel.innerHTML = '';\n    (state.projects||[]).forEach(p => {\n      const o = document.createElement('option');\n      o.value = p; o.textContent = p;\n      sel.appendChild(o);\n    });\n    if (state.project && ![...sel.options].some(o=>o.value===state.project)){\n      const o = document.createElement('option'); o.value=state.project; o.textContent=state.project+' (current)'; sel.appendChild(o);\n    }\n  }\n  if (prev && [...sel.options].some(o=>o.value===prev)) sel.value = prev;\n  else sel.value = state.project || '';\n\n  const msel = $('modelSel');\n  const mopts = state.modelOptions || [];\n  const mkey = JSON.stringify(mopts) + '|' + (state.modelPref || '');\n  if (mkey !== lastModelsKey){\n    lastModelsKey = mkey;\n    msel.innerHTML = '';\n    mopts.forEach(o => { const el = document.createElement('option'); el.value = o.id; el.textContent = o.label; if (o.title) el.title = o.title; msel.appendChild(el); });\n    msel.value = state.modelPref || '';\n  }\n  msel.disabled = !mopts.length;\n\n  $('dot').className = 'dot ' + (state.status||'idle');\n  const stMap = { idle:'Idle', running:'Running', starting:'Starting…', permission:'Awaiting your approval', error:'Error', stopped:'Stopped' };\n  $('stext').textContent = stMap[state.status] || state.status || '';\n\n  const rt = $('resumeTag');\n  if (state.resumeId){ rt.classList.remove('hidden'); rt.textContent = '📎 Resuming · ' + state.resumeId.slice(0,8); }\n  else rt.classList.add('hidden');\n}\n\nfunction renderMessages(){\n  const msgs = state.messages || [];\n  const nearBottom = chat.scrollHeight - chat.scrollTop - chat.clientHeight < 160;\n\n  if (!msgs.length){\n    if (!emptyEl){\n      clearChatNodes();\n      emptyEl = document.createElement('div'); emptyEl.className='empty';\n      chat.appendChild(emptyEl);\n    }\n    emptyEl.textContent = state.status==='starting' ? 'Starting session…' : 'Pick a project and message Claude to begin';\n  } else {\n    if (emptyEl){ emptyEl.remove(); emptyEl = null; }\n    const ids = msgs.map((m,i) => m.id || ('idx'+i));\n    let keep = 0;\n    while (keep < renderedIds.length && keep < ids.length &&\n           renderedIds[keep] === ids[keep] && sigById.get(ids[keep]) === msgSig(msgs[keep])) keep++;\n    for (let i = renderedIds.length - 1; i >= keep; i--){\n      const n = nodeById.get(renderedIds[i]);\n      if (n && n.parentNode) n.parentNode.removeChild(n);\n      nodeById.delete(renderedIds[i]); sigById.delete(renderedIds[i]);\n    }\n    renderedIds.length = keep;\n    for (let i = keep; i < msgs.length; i++){\n      const node = renderMsg(msgs[i]);\n      if (typingEl && typingEl.parentNode === chat) chat.insertBefore(node, typingEl);\n      else chat.appendChild(node);\n      renderedIds.push(ids[i]); nodeById.set(ids[i], node); sigById.set(ids[i], msgSig(msgs[i]));\n    }\n  }\n\n  if (state.status === 'running'){\n    if (!typingEl){ typingEl = document.createElement('div'); typingEl.className='typing'; typingEl.textContent='… thinking / working'; }\n    if (typingEl.parentNode !== chat) chat.appendChild(typingEl);\n  } else if (typingEl){ typingEl.remove(); typingEl = null; }\n  if (nearBottom) chat.scrollTop = chat.scrollHeight;\n}\n\nfunction render(){\n  if (!state) return;\n  renderHead();\n  renderMessages();\n  if (!draftRestored){ draftRestored = true; restoreDraft(); }\n}\n\n/* ---------- 轻量文本渲染：保留换行，代码块等宽可横滚，Markdown 表格转真表格 ----------\n   只处理最常见的三类结构，不做完整 Markdown 解析；所有文本仍走 textContent，\n   不拼 innerHTML，避免把模型输出当 HTML 执行。 */\nfunction inlineFmt(text){\n  const out = document.createDocumentFragment();\n  const re = /(\\*\\*[^*\\n]+\\*\\*|`[^`\\n]+`)/g;\n  let last = 0, m;\n  while ((m = re.exec(text))){\n    if (m.index > last) out.appendChild(document.createTextNode(text.slice(last, m.index)));\n    const tok = m[0];\n    if (tok.startsWith('**')){\n      const b = document.createElement('strong'); b.textContent = tok.slice(2, -2); out.appendChild(b);\n    } else {\n      const c = document.createElement('code'); c.className = 'ic'; c.textContent = tok.slice(1, -1); out.appendChild(c);\n    }\n    last = m.index + tok.length;\n  }\n  if (last < text.length) out.appendChild(document.createTextNode(text.slice(last)));\n  return out;\n}\n\nfunction splitRow(line){\n  let s = line.trim();\n  if (s.startsWith('|')) s = s.slice(1);\n  if (s.endsWith('|')) s = s.slice(0, -1);\n  return s.split('|').map(x => x.trim());\n}\nfunction isTableLine(s){ return /^\\s*\\|.*\\|\\s*$/.test(s); }\nfunction isTableSep(s){ const c = splitRow(s); return c.length > 0 && c.every(x => /^:?-{2,}:?$/.test(x)); }\n\nfunction buildTable(lines){\n  const wrap = document.createElement('div'); wrap.className = 'mtable-wrap';\n  const tbl = document.createElement('table'); tbl.className = 'mtable';\n  const rows = lines.map(splitRow).filter(cells => !cells.every(c => /^:?-{2,}:?$/.test(c)));\n  rows.forEach((cells, idx) => {\n    const tr = document.createElement('tr');\n    cells.forEach(c => {\n      const cell = document.createElement(idx === 0 ? 'th' : 'td');\n      cell.appendChild(inlineFmt(c));\n      tr.appendChild(cell);\n    });\n    tbl.appendChild(tr);\n  });\n  wrap.appendChild(tbl);\n  return wrap;\n}\n\nfunction renderRichText(text){\n  const frag = document.createDocumentFragment();\n  const lines = String(text).split('\\n');\n  let buf = [];\n  const flush = () => {\n    if (!buf.length) return;\n    const d = document.createElement('div'); d.className = 'mtext';\n    d.appendChild(inlineFmt(buf.join('\\n')));\n    frag.appendChild(d);\n    buf = [];\n  };\n\n  for (let i = 0; i < lines.length; i++){\n    const ln = lines[i];\n\n    if (/^\\s*```/.test(ln)){\n      flush();\n      const code = [];\n      for (i++; i < lines.length && !/^\\s*```/.test(lines[i]); i++) code.push(lines[i]);\n      const pre = document.createElement('pre'); pre.className = 'code';\n      pre.textContent = code.join('\\n');\n      frag.appendChild(pre);\n      continue;\n    }\n\n    const h = ln.match(/^\\s{0,3}(#{1,6})\\s+(.*)$/);\n    if (h){\n      flush();\n      const d = document.createElement('div'); d.className = 'mhead h' + h[1].length;\n      d.appendChild(inlineFmt(h[2]));\n      frag.appendChild(d);\n      continue;\n    }\n\n    if (isTableLine(ln)){\n      const rows = [];\n      let j = i;\n      while (j < lines.length && isTableLine(lines[j])) rows.push(lines[j++]);\n      const head = rows.slice(0, 2);\n      if (rows.length >= 2 && head.some(isTableSep)){\n        flush();\n        frag.appendChild(buildTable(rows));\n        i = j - 1;\n        continue;\n      }\n      buf.push(...rows);\n      i = j - 1;\n      continue;\n    }\n\n    buf.push(ln);\n  }\n  flush();\n  return frag;\n}\n\nfunction renderMsg(m){\n  const wrap = document.createElement('div');\n  if (m.role === 'user'){\n    wrap.className='msg user'; wrap.textContent = m.text;\n  }\n  else if (m.role === 'assistant'){\n    wrap.className='msg assistant';\n    if (m.text && (m.text.indexOf('```') >= 0 || /(^|\\n)\\s*\\|.*\\|/.test(m.text))) wrap.classList.add('wide');\n    if (m.thinking){\n      const d = document.createElement('details'); d.className='thinking';\n      const s = document.createElement('summary'); s.textContent='💭 Thinking';\n      const b = document.createElement('div'); b.className='body'; b.textContent = m.thinking;\n      d.appendChild(s); d.appendChild(b); wrap.appendChild(d);\n    }\n    if (m.text) wrap.appendChild(renderRichText(m.text));\n    (m.tools||[]).forEach(t => {\n      const c=document.createElement('div'); c.className='toolcard';\n      const n=document.createElement('div'); n.className='tname'; n.textContent='🛠 ' + t.name;\n      const i=document.createElement('div'); i.className='tinput'; i.textContent = fmtInput(t.input);\n      c.appendChild(n); c.appendChild(i); wrap.appendChild(c);\n    });\n  }\n  else if (m.role === 'tool'){\n    wrap.className='msg tool';\n    (m.results||[]).forEach(r => {\n      const d=document.createElement('div'); d.className='tresult'+(r.error?' err':'');\n      d.textContent = (r.error?'❌ ':'✅ ') + r.text; wrap.appendChild(d);\n    });\n  }\n  else if (m.role === 'approval'){\n    wrap.className='msg approval'; wrap.appendChild(renderApproval(m.card));\n  }\n  else if (m.role === 'error' || m.type==='error'){\n    wrap.className='msg error'; wrap.textContent = m.text || 'An error occurred';\n  }\n  else if (m.role === 'note'){\n    wrap.className='msg note'; wrap.textContent = m.text;\n  }\n  return wrap;\n}\n\nfunction renderApproval(card){\n  const box = document.createElement('div');\n  const t = document.createElement('div'); t.className='ac-title';\n  t.textContent = card.isQuestion ? '❓ Claude has a question' : '🔐 Permission request: ' + card.toolName;\n  box.appendChild(t);\n\n  if (card.isQuestion && Array.isArray(card.questions)){\n    const answers = {};\n    card.questions.forEach((q, qi) => {\n      const row = document.createElement('div'); row.className='q-row';\n      const qt = document.createElement('div'); qt.className='q-text'; qt.textContent = q.question || ('Question '+(qi+1));\n      const opts = document.createElement('div'); opts.className='q-opts';\n      (q.options||[]).forEach(o => {\n        const b = document.createElement('button'); b.className='q-opt'; b.textContent = o.label || o;\n        b.onclick = () => {\n          answers[q.question] = o.label || o;\n          [...opts.children].forEach(x=>x.classList.remove('sel'));\n          b.classList.add('sel');\n        };\n        opts.appendChild(b);\n      });\n      row.appendChild(qt); row.appendChild(opts); box.appendChild(row);\n    });\n    const act = document.createElement('div'); act.className='ac-actions';\n    const done = document.createElement('button'); done.textContent='Submit answer';\n    done.onclick = async () => {\n      if (!Object.keys(answers).length){ toast('Select an option first'); return; }\n      await api('/api/approve', { requestId: card.requestId, decision:'allow', answers });\n      done.textContent='Submitted ✓'; done.disabled = true;\n    };\n    act.appendChild(done); box.appendChild(act);\n  } else {\n    const d = document.createElement('div'); d.className='ac-detail';\n    d.textContent = (card.input ? fmtInput(card.input) : '') ;\n    box.appendChild(d);\n    const act = document.createElement('div'); act.className='ac-actions';\n    const deny = document.createElement('button'); deny.className='danger'; deny.textContent='Deny';\n    deny.onclick = () => api('/api/approve', { requestId: card.requestId, decision:'deny', message:'Denied from phone' });\n    const allow = document.createElement('button'); allow.textContent='Allow';\n    allow.onclick = () => api('/api/approve', { requestId: card.requestId, decision:'allow' });\n    act.appendChild(deny); act.appendChild(allow); box.appendChild(act);\n  }\n  return box;\n}\n\n/* ---------- interactions ---------- */\nfunction start(){\n  $('login').classList.add('hidden'); $('app').classList.remove('hidden');\n  $('msgInput').focus();\n  // SSE 订阅时服务端会立刻下发当前快照,不必再 GET 一份 ——\n  // 原来这里每次都把几百 KB 的 state 拉两遍,是冷启动最大的一笔开销。\n  connect();\n  try { localStorage.setItem('ccb_ready','1'); } catch(e){}\n  // 兜底:2.5s 内还没收到状态就补一次 GET\n  clearTimeout(start._fb);\n  start._fb = setTimeout(async () => {\n    if (state) return;\n    const s = await api('/api/state');\n    if (s) { state = s; render(); }\n  }, 2500);\n}\n\n// 原生壳里没有 localStorage token 时先不闪登录页,等注入脚本用 token 自动登录\nfunction showConnecting(){\n  $('login').classList.add('hidden'); $('app').classList.remove('hidden');\n  if (!state){\n    clearChatNodes();\n    emptyEl = document.createElement('div'); emptyEl.className='empty'; emptyEl.textContent='Connecting…';\n    chat.appendChild(emptyEl);\n  }\n  setTimeout(() => { if (!state) showLogin(); }, 4500);\n}\n\nfunction startDemo(){\n  $('login').classList.add('hidden'); $('app').classList.remove('hidden');\n  state = demoSnapshot(); render();\n  $('msgInput').focus();\n  toast('Demo mode — sample data only');\n}\n\n$('btnLogin').onclick = doLogin;\n$('tokenInput').addEventListener('keydown', e => { if (e.key==='Enter') doLogin(); });\n\n$('projectSel').onchange = async (e) => {\n  const p = e.target.value; if (!p) return;\n  const s = await api('/api/session', { project:p, fresh:true });\n  if (s){ state=s; render(); }\n};\n$('btnNew').onclick = async () => {\n  const p = $('projectSel').value;\n  const s = await api('/api/session', { project:p, fresh:true });\n  if (s){ state=s; render(); }\n};\n$('modelSel').onchange = async (e) => {\n  const m = e.target.value;\n  const s = await api('/api/runner/model', { model:m });\n  if (s){ state=s; render(); }\n  const lab = e.target.selectedOptions[0] ? e.target.selectedOptions[0].textContent : 'Default';\n  toast('Model → ' + lab + ' · applies to next message');\n};\n$('btnStop').onclick = async () => { const s = await api('/api/stop'); if (s){ state=s; render(); } };\n$('btnSend').onclick = sendMsg;\n\n/* ---------- session history ---------- */\nfunction fmtTime(ts){\n  if (!ts) return '';\n  const diff = Date.now() - ts;\n  if (diff < 60000) return 'just now';\n  if (diff < 3600000) return Math.floor(diff/60000)+' min ago';\n  if (diff < 86400000) return Math.floor(diff/3600000)+' hr ago';\n  if (diff < 7*86400000) return Math.floor(diff/86400000)+' d ago';\n  const d = new Date(ts);\n  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\n}\nasync function openHistory(){\n  const r = await api('/api/sessions');\n  const list = $('histList'); list.innerHTML = '';\n  const ss = (r && r.sessions) || [];\n  if (!ss.length){\n    const d = document.createElement('div'); d.className='hist-empty'; d.textContent='No past sessions'; list.appendChild(d);\n    $('histOverlay').classList.remove('hidden'); return;\n  }\n  ss.forEach(s => {\n    const item = document.createElement('div'); item.className='hist-item';\n    const t = document.createElement('div'); t.className='hist-title';\n    t.textContent = s.title || s.firstMsg || '(Untitled session)';\n    const m = document.createElement('div'); m.className='hist-meta';\n    const tm = document.createElement('span'); tm.textContent = fmtTime(s.lastAt);\n    const proj = document.createElement('span'); proj.className='proj'; proj.textContent = s.project;\n    const mdl = document.createElement('span'); mdl.textContent = s.model || '';\n    const sz = document.createElement('span'); sz.textContent = Math.round(s.size/1024)+'KB';\n    m.appendChild(tm); m.appendChild(proj); m.appendChild(mdl); m.appendChild(sz);\n    item.appendChild(t); item.appendChild(m);\n    item.onclick = () => resumeSession(s);\n    list.appendChild(item);\n  });\n  $('histOverlay').classList.remove('hidden');\n}\nasync function resumeSession(s){\n  $('histOverlay').classList.add('hidden');\n  toast('Importing session…');\n  // resume needs the original session's project dir as cwd (claude --resume depends on cwd)\n  const project = s.project || $('projectSel').value || state.project;\n  const res = await api('/api/session', { project, fresh:false, resumeId: s.id });\n  if (res){\n    state = res; render();\n    const holders = res.holders || [];\n    const released = res.released || [];\n    if (holders.length){\n      toast('⚠ 电脑端正开着这条会话（' + holders.map(h => h.entrypoint === 'claude-vscode' ? 'VSCode' : (h.entrypoint || '电脑端')).join(', ') + '）：手机的新消息电脑端不会自动刷新，回电脑后请关掉这条会话再重新打开', 6000);\n    } else if (released.length){\n      toast('已让电脑端让位 · 回电脑重新打开这条会话就能看到手机上的记录', 5000);\n    } else {\n      toast('Resumed: ' + (s.title || s.id.slice(0,8)));\n    }\n  }\n}\n$('btnHist').onclick = openHistory;\n$('histClose').onclick = () => $('histOverlay').classList.add('hidden');\n\nconst ta = $('msgInput');\nta.addEventListener('keydown', e => {\n  if (e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendMsg(); }\n});\nta.addEventListener('input', () => { ta.style.height='auto'; ta.style.height=Math.min(ta.scrollHeight,120)+'px'; saveDraft(); });\n\n/* ---------- 草稿持久化 ----------\n   iOS 切后台会挂起 WKWebView，App 回前台时原生层强制 reload 重连 SSE，\n   页面连同 textarea 里没发出去的半截文字一起被销毁 → 回来就没了。\n   这里把草稿写进 localStorage（按项目区分），页面重载后原样填回。 */\nconst DRAFT_KEY = 'ccb_draft';\nfunction saveDraft(){\n  try {\n    localStorage.setItem(DRAFT_KEY, JSON.stringify({\n      text: ta.value,\n      project: (state && state.project) || null\n    }));\n  } catch(e){}\n}\nfunction clearDraft(){ try { localStorage.removeItem(DRAFT_KEY); } catch(e){} }\nfunction restoreDraft(){\n  try {\n    if (ta.value) return;                      // 已经有内容（例如注入脚本重复 start）就别覆盖\n    const raw = localStorage.getItem(DRAFT_KEY);\n    if (!raw) return;\n    const d = JSON.parse(raw);\n    if (!d || typeof d.text !== 'string' || !d.text){ clearDraft(); return; }\n    const cur = (state && state.project) || null;\n    if (d.project && cur && d.project !== cur) return;   // 项目不同就不回填，免得发错地方\n    ta.value = d.text;\n    ta.style.height='auto'; ta.style.height=Math.min(ta.scrollHeight,120)+'px';\n  } catch(e){}\n}\n\nasync function sendMsg(){\n  const text = ta.value.trim(); if (!text) return;\n  ta.value=''; ta.style.height='auto';\n  clearDraft();\n  const r = await api('/api/message', { text });\n  if (r && r.error) toast(r.error);\n}\n\n// notify when the network drops\nwindow.addEventListener('offline', ()=>setStatus('Offline'));\nwindow.addEventListener('online', ()=>setStatus('Connected'));\n\n// startup\nif (DEMO) startDemo();\nelse if (savedToken || lsGet('ccb_ready')) start();   // 第二次起直接连,不再先闪登录页\nelse if (window.ReactNativeWebView) showConnecting();  // 原生壳:等注入的 token auto-login\nelse showLogin();\n</script>\n</body>\n</html>\n";
